/**
 * HEALTH ASSIST PHASE 5 — the ITOM decision table: one entry per workbook rule.
 *
 * `scripts/build-itom-catalogue.mjs` turns this into the three generated files
 * (architecture map, parameter declarations, rule configurations). Every rule
 * is in exactly one of five states, and the state is a DECISION recorded here,
 * with its reason, where a reviewer reads it:
 *
 *   executable           the workbook defines the detection, and the tables it
 *                        needs are named in `requires_tables` — verified on THIS
 *                        instance by the runner before anything is read
 *   unconfigured         executable, but a threshold the workbook leaves open
 *                        (declared UNDEFINED, never invented) must be set first
 *   undefined            the workbook leaves part of the DETECTION undefined (a
 *                        classification, a policy, a matrix, provider data);
 *                        `undefined_dependencies` names it
 *   object unverified    the detection needs a platform object whose table is
 *                        not established; `requires_objects` names the concept
 *                        and its candidate, resolved by the DECISION 5 pipeline
 *   not built            fully defined; its evaluator is not built in this stage
 *                        (`build_pending`)
 *   equivalent           the same condition as a CMDB rule already built
 *                        (ownership OWN-001 / OWN-002): evaluated once, there
 *
 * Nothing here is a guess dressed as a fact: a candidate table is verified at
 * run time, a platform value is read from sys_choice by its label, and an
 * unverified object makes a rule UNAVAILABLE — never PASS.
 */

const T = (table, ...fields) => ({ table, fields });
const choice = (table, element, label) => ({ $choice: { table, element, label } });
/* `source`: the recorded decision that took a default from ServiceNow's documentation (D-033) — never a guess. */
const P = (key, type, unit, dflt, description, source = null) => ({ key, type, unit, default: dflt, description, ...(source ? { source } : {}) });
const param = (key) => ({ $param: key });
const win = (key) => ({ $param: key, as: 'window' });
const undef = (...deps) => ({ undefined_dependencies: deps });
const pending = (text) => ({ build_pending: text });
const gap = (missing) => ({ specification_gap: { missing } });
const needs = (...objects) => ({ requires_objects: objects });

const SCHEDULE = T('discovery_schedule', 'name', 'active', 'discover', 'run_type', 'run_period', 'max_run', 'mid_select_method', 'mid_server', 'location');
/* Phase 5E: a range reaches a schedule directly (`schedule`) or through its range set (`parent` → discovery_schedule_range, read when the instance has it). */
const RANGE_ITEM = T('discovery_range_item', 'name', 'schedule', 'parent', 'type', 'start_ip_address', 'end_ip_address', 'network_ip', 'netmask', 'active');
const STATUS = T('discovery_status', 'dscheduler', 'state', 'started', 'completed');
const DEVICE = T('discovery_device_history', 'status', 'source');
const CRED = T('discovery_credentials', 'name', 'active', 'type', 'sys_created_on', 'sys_updated_on');
/* Phase 5E: verified on a real instance — the affinity table is dscy_credentials_affinity. */
const AFFINITY = T('dscy_credentials_affinity', 'credential_id', 'ip_address');
const AGENT = T('ecc_agent', 'name', 'status', 'validated', 'last_refreshed', 'version', 'host_name', 'user_name');
const CLUSTER = T('ecc_agent_cluster_member_m2m', 'agent', 'cluster');
const ALERT = T('em_alert', 'number', 'cmdb_ci', 'severity', 'state', 'source', 'node', 'acknowledged', 'message_key');
const EVENT = T('em_event', 'source', 'node', 'cmdb_ci', 'severity', 'state', 'message_key', 'time_of_event');
const ASSOC = T('svc_ci_assoc', 'service_id', 'ci_id');

const COMPLETED = choice('discovery_status', 'state', 'Completed');
/* Phase 5E: the label is "Canceled" on a real instance, "Cancelled" on others — either, provided both name one value. */
const CANCELLED = choice('discovery_status', 'state', ['Canceled', 'Cancelled']);
const SPECIFIC_MID = choice('discovery_schedule', 'mid_select_method', 'Specific MID Server');
const ACTIVE_SCHEDULES = 'active=true';
/* D-037: the CSDM layer classifications (as the CSDM pack), for walking a service model. */
const SERVICE_CLASSIFICATION = { business: choice('cmdb_ci_service', 'service_classification', 'Business Service'), technical: choice('cmdb_ci_service', 'service_classification', 'Technology Management Service'), application: choice('cmdb_ci_service', 'service_classification', 'Application Service') };
const INTERVALS = [
  { value: choice('discovery_schedule', 'run_type', 'Daily'), every: '1 days' },
  { value: choice('discovery_schedule', 'run_type', 'Weekly'), every: '7 days' },
  { value: choice('discovery_schedule', 'run_type', 'Monthly'), every: '1 months' },
  { value: choice('discovery_schedule', 'run_type', 'Periodically'), every: 'run_period' },
];

/* Reused reasons, so the same gap reads the same wherever it appears. */
const R = {
  deviceOutcome: 'the per-device phase outcome (port scan / classification / exploration reached) — its field and value set on discovery_device_history are not established on any instance this build has verified',
  credentialAttempt: 'per-credential authentication outcomes per range per day: the platform records a credential affinity on SUCCESS, but no table the workbook names records each failed attempt against the credential tried',
  deviceType: 'a device-type inference from port signatures and partial classification — the workbook names the idea, not the signature → type mapping',
  patternExecution: 'pattern execution results per pattern and device class (success, failure, step timeouts) — no execution-result table is established',
  mapRefresh: 'service map refresh history (last refresh, configured interval, CI count per refresh run) — no refresh-run object is established',
  mapTopology: 'the service map\'s own topology as distinct from cmdb_rel_ci — no map-edge object is established',
  connector: 'connector instance run state (status, last successful pull, interval, errors) — the fields of em_connector_instance that carry it are not established',
  eventRules: 'the CI class set each event rule covers — event rules filter on conditions, and the workbook defines no reading of a condition as a class set',
  impact: 'impact calculation results per alert (affected services) — the impact object is not established',
  alertRules: 'alert management rule definitions with their actions, firing counts and incident-creation configuration — not established',
  cloudAccounts: 'the registry of cloud service accounts with their regions and discovery scope — not established',
  cloudProvisioning: 'Cloud Provisioning and Governance objects (blueprints, provisioning workflows, policies, quotas, approvals) — not established, and only present where that product is licensed',
  duplicates: 'duplicate-set membership with the source that created each member — owned by the CMDB duplicate rules; consumed here once the cross-domain link is built',
};

